function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}
function sqlJson(value) {
  return `${sql(JSON.stringify(value ?? {}))}::jsonb`;
}
function slug(value, fallback = '') { return String(value || fallback || '').trim(); }
const body=$json.body||{}; const avatar=slug(body.avatar); const scene=slug(body.scene); const status=slug(body.status,''); const limit=Number(body.limit||50); const where=[]; if(avatar)where.push(`avatar=${sql(avatar)}`); if(scene)where.push(`scene=${sql(scene)}`); if(status)where.push(`status=${sql(status)}`); const wc=where.length?'WHERE '+where.join(' AND '):''; const query=`SELECT * FROM publication_drafts ${wc} ORDER BY updated_at DESC LIMIT ${Number.isFinite(limit)?limit:50};`; return {json:{query}};

function parse(v, fallback) {
  if (v == null) return fallback;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch { return fallback; }
  }
  return v;
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((row) => row.draft_id);

const drafts = rows.map((r) => ({
  draftId: r.draft_id,
  avatar: r.avatar,
  scene: r.scene,
  assetType: r.asset_type,
  platform: r.platform,
  assetId: r.asset_id,
  generatedAssetId: r.generated_asset_id,
  imageUrl: r.image_url,
  caption: r.caption,
  hashtags: parse(r.hashtags, []),
  status: r.status,
  createdAt: r.created_at,
  updatedAt: r.updated_at,
  approvedAt: r.approved_at,
}));

return [{ json: { ok: true, count: drafts.length, drafts } }];
